def mri_coreg_execute(params: MriCoreg, runner: Runner | None = None) -> MriCoregOutputs:
    """
    mri_coreg

    mri_coreg performs a linear registration between two volumes using the method compatible with spm_coreg.

    Author: FreeSurfer Developers

    URL: https://github.com/freesurfer/freesurfer

    Args:
        params: The parameters.
        runner: Command runner (defaults to global runner).

    Returns:
        Tool outputs (paths to files produced by the tool).
    """
    mri_coreg_validate(params)
    runner = runner if runner is not None else get_global_runner()
    execution = runner.start_execution(MRI_COREG_METADATA)
    execution.params(params)
    args = mri_coreg_cargs(params, execution)
    out = mri_coreg_outputs(params, execution)
    execution.run(args)
    return out

